CREATE OR REPLACE FUNCTION kablet_visitor_privacy_delete(p_organization_id uuid, p_visitor_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE deleted boolean; BEGIN IF p_organization_id <> kablet_current_org() THEN RAISE EXCEPTION 'privacy tenant mismatch'; END IF; DELETE FROM visitor_states WHERE organization_id = p_organization_id AND visitor_identity_id = p_visitor_id; DELETE FROM visitor_observations WHERE organization_id = p_organization_id AND visitor_identity_id = p_visitor_id; DELETE FROM visitor_state_revisions WHERE organization_id = p_organization_id AND visitor_identity_id = p_visitor_id; DELETE FROM visitor_sessions WHERE organization_id = p_organization_id AND visitor_identity_id = p_visitor_id; DELETE FROM visitor_identities WHERE organization_id = p_organization_id AND id = p_visitor_id RETURNING true INTO deleted; RETURN COALESCE(deleted, false); END $$;
REVOKE ALL ON FUNCTION kablet_visitor_privacy_delete(uuid, uuid) FROM PUBLIC;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'kablet_dev') THEN GRANT EXECUTE ON FUNCTION kablet_visitor_privacy_delete(uuid, uuid) TO kablet_dev; END IF; IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'kablet_test_manager') THEN GRANT EXECUTE ON FUNCTION kablet_visitor_privacy_delete(uuid, uuid) TO kablet_test_manager; END IF; END $$;
CREATE OR REPLACE FUNCTION kablet_visitor_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF current_user <> pg_get_userbyid((SELECT proowner FROM pg_proc WHERE oid = 'kablet_visitor_privacy_delete(uuid,uuid)'::regprocedure)) THEN RAISE EXCEPTION 'visitor history is immutable'; END IF; RETURN OLD; END $$;
DROP TRIGGER IF EXISTS visitor_observations_immutable ON visitor_observations; CREATE TRIGGER visitor_observations_immutable BEFORE UPDATE OR DELETE ON visitor_observations FOR EACH ROW EXECUTE FUNCTION kablet_visitor_immutable();
DROP TRIGGER IF EXISTS visitor_state_revisions_immutable ON visitor_state_revisions; CREATE TRIGGER visitor_state_revisions_immutable BEFORE UPDATE OR DELETE ON visitor_state_revisions FOR EACH ROW EXECUTE FUNCTION kablet_visitor_immutable();
